def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    count = 2

    if count == 0:
        return None

    value = (v1 + v2) / count

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "count": count,
            "average": value,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares"
            }
        }
    }
